/** 阿拉伯數字 → 天城文數字（U+0966 ० 起，逐位映射；確保數字無誤的唯一通道）。 */
export function toDevanagariDigits(n: number): string {
  return String(n).split("").map((d) => {
    const v = Number(d);
    if (!Number.isInteger(v) || v < 0 || v > 9) throw new Error(`非十進位位元: ${d}`);
    return String.fromCodePoint(0x0966 + v);
  }).join("");
}

/** 生成單個序號 SVG（24×24，純 path 輪廓，currentColor，與品牌 icon 同渲染方式）。 */
export function numberIconSvg(n: number): string {
  const key = String(n);
  const body = DEVA_GLYPHS[key];
  if (!body) throw new Error(`未預生成序號字形: ${n}`);
  // addIcon 外層 svg 固定 viewBox 0 0 100 100（官方 DM 常量）；字形座標已預縮放到 100 基準，
  // 直接返回 path 內容、不包內層 svg——嵌套 svg 在部分行動 WebView 預設尺寸為 0，會整個空白。
  return body;
}
